command:
set -o pipefail
cd "$(git rev-parse --show-toplevel)" && mkdir -p temp && cat > temp/repro.py <<'EOF'
import click
from click.testing import CliRunner

class CustomArg(click.Argument):
    pass

class CustomOpt(click.Option):
    pass

shared_arg = click.argument("name", cls=CustomArg)
shared_opt = click.option("--name", cls=CustomOpt)

@click.command()
@shared_arg
def cmd1(name):
    click.echo(type(name).__name__)

@click.command()
@shared_arg
def cmd2(name):
    click.echo(type(name).__name__)

@click.command()
@shared_opt
def ocmd1(name):
    click.echo(type(name).__name__)

@click.command()
@shared_opt
def ocmd2(name):
    click.echo(type(name).__name__)

r = CliRunner()
print("arg cmd1:", r.invoke(cmd1, ["x"]).output.strip())
print("arg cmd2:", r.invoke(cmd2, ["x"]).output.strip())
print("opt cmd1:", r.invoke(ocmd1, ["--name", "x"]).output.strip())
print("opt cmd2:", r.invoke(ocmd2, ["--name", "x"]).output.strip())
print("cmd1 param class:", type(cmd1.params[0]).__name__)
print("cmd2 param class:", type(cmd2.params[0]).__name__)
EOF
PYTHONPATH=src python -B temp/repro.py
